# Device-resident left-looking Cholesky for the one high-batch N=512 cell.
# One CTA owns each matrix for the full factorization; the 32x32 MathDx panel
# factorization, triangular solves, and FP16-input/FP32-accumulate updates all
# remain in the caller's launch sequence.
_DX_N = 512
_DX_NB = 32
_DX_NT = 128
_DX_MATRIX_ELEMENTS = _DX_N * _DX_N
_DX_TILE_ELEMENTS = _DX_NB * _DX_NB
_DX_LOADS_PER_THREAD = _DX_TILE_ELEMENTS // _DX_NT
_DX_ROW_STRIDE = _DX_NT // _DX_NB
_DX_GLOBAL_ROW_STRIDE = _DX_ROW_STRIDE * _DX_N

@cuda.jit(device=True, forceinline=True)
def _g2048_load_first_diagonal_update(
    source, destination, sample_base, tile, diagonal, update, leading
):
    tid = cuda.threadIdx.x
    origin = tile * _G2048_NB
    row = tid // _G2048_NB
    col = tid - row * _G2048_NB
    index = tid
    source_index = sample_base + (origin + row) * leading + origin + col
    update_index = sample_base + row * leading + origin + col
    global_row_stride = _G2048_ROW_STRIDE * leading
    for _ in range(_G2048_LOADS_PER_THREAD):
        if row <= col:
            diagonal[index] = source[source_index]
        update[index] = destination[update_index]
        row += _G2048_ROW_STRIDE
        index += _G2048_NT
        source_index += global_row_stride
        update_index += global_row_stride
    cuda.syncthreads()


@cuda.jit(device=True, forceinline=True)
def _g2048_load_tile(
    source, sample_base, tile_row, tile_col, shared, leading
):
    tid = cuda.threadIdx.x
    row_origin = tile_row * _G2048_NB
    col_origin = tile_col * _G2048_NB
    row = tid // _G2048_NB
    col = tid - row * _G2048_NB
    index = tid
    source_index = (
        sample_base + (row_origin + row) * leading + col_origin + col
    )
    global_row_stride = _G2048_ROW_STRIDE * leading
    for _ in range(_G2048_LOADS_PER_THREAD):
        shared[index] = source[source_index]
        index += _G2048_NT
        source_index += global_row_stride
    cuda.syncthreads()


@cuda.jit(device=True, forceinline=True)
def _g2048_load_tile_pair(
    source,
    sample_base,
    first_row,
    first_col,
    first,
    second_col,
    second,
    leading,
):
    tid = cuda.threadIdx.x
    first_row_origin = first_row * _G2048_NB
    first_col_origin = first_col * _G2048_NB
    second_col_origin = second_col * _G2048_NB
    row = tid // _G2048_NB
    col = tid - row * _G2048_NB
    index = tid
    global_row = first_row_origin + row
    first_index = sample_base + global_row * leading + first_col_origin + col
    second_index = sample_base + global_row * leading + second_col_origin + col
    global_row_stride = _G2048_ROW_STRIDE * leading
    for _ in range(_G2048_LOADS_PER_THREAD):
        first[index] = source[first_index]
        second[index] = source[second_index]
        index += _G2048_NT
        first_index += global_row_stride
        second_index += global_row_stride
    cuda.syncthreads()


@cuda.jit(device=True, forceinline=True)
def _g2048_load_first_panel_update(
    source,
    destination,
    sample_base,
    tile_row,
    tile_col,
    accumulator,
    first,
    second,
    leading,
):
    tid = cuda.threadIdx.x
    source_row_origin = tile_row * _G2048_NB
    source_col_origin = tile_col * _G2048_NB
