    second_col_origin = tile_col * _G2048_NB
    row = tid // _G2048_NB
    col = tid - row * _G2048_NB
    index = tid
    accumulator_index = (
        sample_base
        + (source_row_origin + row) * leading
        + source_col_origin
        + col
    )
    first_index = sample_base + row * leading + first_col_origin + col
    second_index = sample_base + row * leading + second_col_origin + col
    global_row_stride = _G2048_ROW_STRIDE * leading
    for _ in range(_G2048_LOADS_PER_THREAD):
        accumulator[index] = source[accumulator_index]
        first[index] = destination[first_index]
        second[index] = destination[second_index]
        index += _G2048_NT
        accumulator_index += global_row_stride
        first_index += global_row_stride
        second_index += global_row_stride
    cuda.syncthreads()


