@cuda.jit
def _g2048_potrf(
    source, destination, leading, matrix_elements, panel_origin
):
    sample = cuda.blockIdx.x
    sample_base = (
        sample * matrix_elements + panel_origin * (leading + 1)
    )
    shared = cuda.shared.array(shape=0, dtype=np.float32, alignment=16)
    a_shared = shared[0:_G2048_TILE_ELEMENTS]
    b_shared = shared[_G2048_TILE_ELEMENTS : 2 * _G2048_TILE_ELEMENTS]
    update_shared = shared[
        2 * _G2048_TILE_ELEMENTS : 3 * _G2048_TILE_ELEMENTS
    ].view(np.float16)
    c_shared = update_shared[0:_G2048_TILE_ELEMENTS]
    d_shared = update_shared[_G2048_TILE_ELEMENTS : 2 * _G2048_TILE_ELEMENTS]
    local_info = shared[3 * _G2048_TILE_ELEMENTS :].view(np.int32)

    tile_count = _G2048_N // _G2048_NB
    for k in range(tile_count):
        if k == 0:
            _g2048_load_diagonal(
                source, sample_base, k, a_shared, leading
            )
        else:
            _g2048_load_first_diagonal_update(
                source,
                destination,
                sample_base,
                k,
                a_shared,
                c_shared,
                leading,
