            _g2048_gemm.execute(-1.0, c_shared, c_shared, 1.0, a_shared)
            cuda.syncthreads()

        _g2048_cholesky.factorize(a_shared, local_info, lda=_G2048_NB)
        if k + 1 == tile_count:
            _g2048_store_tile(
                a_shared, destination, sample_base, k, k, True, leading
            )

        for j in range(k + 1, tile_count):
            if k == 0:
                if j == k + 1:
                    _g2048_store_diagonal_and_load_panel(
                        a_shared,
                        destination,
                        source,
                        sample_base,
                        k,
                        j,
                        b_shared,
                        leading,
                    )
                else:
                    _g2048_load_tile(
                        source, sample_base, k, j, b_shared, leading
                    )
            else:
                if j == k + 1:
                    _g2048_store_diagonal_and_load_first_panel_update(
                        a_shared,
                        source,
                        destination,
                        sample_base,
                        k,
                        j,
                        b_shared,
                        c_shared,
                        d_shared,
                        leading,
                    )
                else:
                    _g2048_load_first_panel_update(
                        source,
                        destination,
                        sample_base,
                        k,
                        j,
                        b_shared,
                        c_shared,
                        d_shared,
                        leading,
