                cuda.syncthreads()
            for i in range(1, k):
                _g2048_load_tile_pair(
                    destination,
                    sample_base,
                    i,
                    k,
                    c_shared,
                    j,
                    d_shared,
                    leading,
                )
                _g2048_gemm.execute(-1.0, c_shared, d_shared, 1.0, b_shared)
