def _grouped_mathdx_cholesky(
    data: torch.Tensor,
    output: torch.Tensor,
    pointers: torch.Tensor,
    output_view,
) -> torch.Tensor:
    n = output.shape[-1]
    block = _G2048_N
    _ext.grouped_prepare_(data, output)
    for panel_origin in range(0, n, block):
        _launch_g2048(
            output_view,
            output_view,
            output.shape[0],
            n,
            n * n,
            panel_origin,
        )
        _ext.grouped_panel_update_(
            output, pointers, block, panel_origin // block
        )
    return _ext.grouped_finish(output)


