    logger.log("test-count", len(tests))
    for index, test in enumerate(tests):
        logger.log(f"test.{index}.spec", test.spec)
        good, message = _run_single_test(test)
        logger.log(f"test.{index}.status", "pass" if good else "fail")
        if message:
            logger.log(
                f"test.{index}.message" if good else f"test.{index}.error", message
            )
        passed = passed and good
    logger.log("check", "pass" if passed else "fail")
    return 0 if passed else 112


def _benchmark_batch_count(test: TestCase) -> int:
    batch = int(test.args.get("batch", 1))
    n = int(test.args.get("n", 1))
    bytes_per_input = batch * n * n * 4
    return max(
        1,
        min(
            MAX_ITERATIONS_PER_BENCHMARK,
            BENCHMARK_INPUT_BYTES_TARGET // bytes_per_input,
        ),
    )


def _make_data_batch(test: TestCase, count: int) -> list[torch.Tensor]:
    args = dict(test.args)
    data_list = []
    for _ in range(count):
        data_list.append(generate_input(**args))
        if "seed" in args:
            args["seed"] += 42
    return data_list


def _run_single_benchmark(
    test: TestCase,
    recheck: bool,
    max_repeats: int,
    max_time_ns: float,
) -> Stats | str:
    from submission import custom_kernel

    data_list = _make_data_batch(test, _benchmark_batch_count(test))
    check_copy = [_clone_data(data) for data in data_list]
    outputs = [custom_kernel(_clone_data(data)) for data in data_list]
    torch.cuda.synchronize()
    for reference_data, output in zip(check_copy, outputs, strict=True):
        good, message = check_implementation(reference_data, output)
        if not good:
            return message

    durations = []
    benchmark_start = time.perf_counter_ns()
    for iteration in range(max_repeats):
        torch.cuda.synchronize()
        clear_l2_cache()
        start = torch.cuda.Event(enable_timing=True)
        end = torch.cuda.Event(enable_timing=True)
        start.record()
        outputs = [custom_kernel(data) for data in data_list]
        end.record()
        torch.cuda.synchronize()
        durations.append(start.elapsed_time(end) * 1e6 / len(data_list))

        if recheck:
            for reference_data, output in zip(check_copy, outputs, strict=True):
                good, message = check_implementation(reference_data, output)
                if not good:
                    return message

        elapsed = time.perf_counter_ns() - benchmark_start
        if iteration > 1 and elapsed > 1e8:
            stats = calculate_stats(durations)
            if (
                stats.err / stats.mean < 0.001
                or stats.mean * stats.runs > max_time_ns
                or elapsed > 120e9
            ):
                break
    return calculate_stats(durations)


def _log_benchmark(
    logger: PopcornOutput, index: int, test: TestCase, result: Stats | str
) -> bool:
    logger.log(f"benchmark.{index}.spec", test.spec)
    if not isinstance(result, Stats):
        logger.log(f"benchmark.{index}.status", "fail")
        logger.log(f"benchmark.{index}.error", result)
        return False
    for field in dataclasses.fields(Stats):
        logger.log(f"benchmark.{index}.{field.name}", getattr(result, field.name))
    return True


def run_benchmarking(
    logger: PopcornOutput, tests: list[TestCase], leaderboard: bool = False
) -> int:
    _run_single_benchmark(tests[0], False, 20, 1e8)
    max_repeats = 1000 if leaderboard else 200
    max_time_ns = 30e9 if leaderboard else 10e9
    passed = True
    logger.log("benchmark-count", len(tests))
    for index, test in enumerate(tests):
        result = _run_single_benchmark(test, True, max_repeats, max_time_ns)
        passed = _log_benchmark(logger, index, test, result) and passed
        if leaderboard and not passed:
            break
    logger.log("check", "pass" if passed else "fail")
    return 0 if passed else 112


def run_profiling(logger: PopcornOutput, tests: list[TestCase]) -> int:
    from submission import custom_kernel

    test = tests[0]
    logger.log("benchmark-count", 1)
    logger.log("benchmark.0.spec", test.spec)
    with nvtx_range("generate input"):
        data = generate_input(**test.args)
        torch.cuda.synchronize()
    with nvtx_range("custom_kernel"):
        output = custom_kernel(_clone_data(data))
        torch.cuda.synchronize()
    good, message = check_implementation(data, output)
    if not good:
        logger.log("benchmark.0.status", "fail")
        logger.log("benchmark.0.error", message)
    logger.log("check", "pass" if good else "fail")
    return 0 if good else 112


def main() -> int:
    fd = os.getenv("POPCORN_FD")
    if not fd:
        return 111
    if len(sys.argv) < 3:
        return 2

    mode = sys.argv[1]
    seed = os.getenv("POPCORN_SEED")
    os.unsetenv("POPCORN_SEED")
    seed_value = int(seed) if seed else None
    set_seed(seed_value or 42)
    tests = get_test_cases(sys.argv[2], seed_value)

    with PopcornOutput(int(fd)) as logger:
        if mode == "test":
            return run_testing(logger, tests)
        if mode == "benchmark":
            return run_benchmarking(logger, tests)
        if mode == "leaderboard":
            return run_benchmarking(logger, tests, leaderboard=True)
        if mode == "profile":
            return run_profiling(logger, tests)
        return 2


if __name__ == "__main__":
    sys.exit(main())
import torch

from task import input_t, output_t


_RECON_RTOL_FACTOR = 20.0
_TRIANGULAR_RTOL_FACTOR = 8.0


def _symmetrize(a: torch.Tensor) -> torch.Tensor:
    return 0.5 * (a + a.transpose(-1, -2))


def _random_orthogonal(
    batch: int,
    n: int,
    gen: torch.Generator,
    device: torch.device,
) -> torch.Tensor:
    x = torch.randn((batch, n, n), device=device, dtype=torch.float32, generator=gen)
    q, r = torch.linalg.qr(x)
    signs = torch.where(
        torch.diagonal(r, dim1=-2, dim2=-1) >= 0,
        torch.ones((), device=device),
        -torch.ones((), device=device),
    )
    return q * signs.unsqueeze(-2)


def _dense_spd(a: torch.Tensor, damping: float) -> torch.Tensor:
    n = a.shape[-1]
    out = (a @ a.transpose(-1, -2)) / float(max(n, 1))
    out.diagonal(dim1=-2, dim2=-1).add_(damping)
    return _symmetrize(out).contiguous()


def generate_input(
    batch: int,
    n: int,
    cond: int,
    seed: int,
    case: str = "dense",
) -> input_t:
    assert batch > 0, "batch must be positive"
    assert n > 0, "n must be positive"
    assert cond >= 0, "cond must be non-negative"

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    gen = torch.Generator(device=device)
    gen.manual_seed(seed)
    case = case.lower()

    if case == "dense":
        a = torch.randn(
            (batch, n, n), device=device, dtype=torch.float32, generator=gen
        )
        return _dense_spd(a, 10.0 ** -max(cond, 2))

    if case == "diagonal":
        diagonal = torch.logspace(
            0.0,
            -float(max(cond, 1)),
            n,
            device=device,
            dtype=torch.float32,
        )
        return torch.diag_embed(diagonal.expand(batch, n)).contiguous()

    if case == "spectrum":
        values = torch.logspace(
            0.0,
            -float(max(cond, 1)),
            n,
            device=device,
            dtype=torch.float32,
        ).expand(batch, n)
        q = _random_orthogonal(batch, n, gen, device)
        return _symmetrize(
            (q * values.unsqueeze(-2)) @ q.transpose(-1, -2)
        ).contiguous()

    if case == "lowrank":
        rank = max(1, min(n // 8, 64))
        factors = torch.randn(
            (batch, n, rank),
            device=device,
            dtype=torch.float32,
            generator=gen,
        )
        out = (factors @ factors.transpose(-1, -2)) / float(rank)
        out.diagonal(dim1=-2, dim2=-1).add_(10.0 ** -max(cond, 3))
        return _symmetrize(out).contiguous()

    if case == "rowscale":
        a = torch.randn(
            (batch, n, n), device=device, dtype=torch.float32, generator=gen
        )
        base = _dense_spd(a, 1.0e-3)
        scales = torch.logspace(
            0.0,
            -0.5 * float(max(cond, 2)),
            n,
            device=device,
            dtype=torch.float32,
        )
        out = scales.reshape(1, n, 1) * base * scales.reshape(1, 1, n)
        out.diagonal(dim1=-2, dim2=-1).add_(1.0e-6)
        return _symmetrize(out).contiguous()

    if case == "tridiagonal":
        diagonal = torch.empty((batch, n), device=device, dtype=torch.float32).uniform_(
            1.5, 2.5, generator=gen
        )
        off_diagonal = torch.empty(
            (batch, max(n - 1, 0)), device=device, dtype=torch.float32
        ).uniform_(-0.25, 0.25, generator=gen)
        out = torch.diag_embed(diagonal)
        if n > 1:
            out = (
                out
                + torch.diag_embed(off_diagonal, offset=1)
                + torch.diag_embed(off_diagonal, offset=-1)
            )
        return out.contiguous()

    raise ValueError(f"unknown Cholesky test case: {case}")


def ref_kernel(data: input_t) -> output_t:
    return torch.linalg.cholesky_ex(data, check_errors=False).L


def _matrix_l1_norm(value: torch.Tensor) -> torch.Tensor:
    return torch.linalg.matrix_norm(value, ord=1, dim=(-2, -1))


def check_implementation(data: input_t, output: output_t) -> tuple[bool, str]:
    if not isinstance(output, torch.Tensor):
        return False, "output must be a torch.Tensor"
    if output.shape != data.shape:
        return (
            False,
            f"output shape must be {tuple(data.shape)}, got {tuple(output.shape)}",
        )
    if output.dtype != torch.float32:
        return False, f"output dtype must be torch.float32, got {output.dtype}"
    if output.device != data.device:
        return False, f"output must be on {data.device}, got {output.device}"
    if not torch.isfinite(output).all().item():
        return False, "output contains NaN or Inf"

    batch, n, _ = data.shape
    eps = torch.finfo(torch.float32).eps
    scale = _matrix_l1_norm(data).clamp_min(torch.finfo(torch.float32).tiny)

    upper = torch.triu(output, diagonal=1)
    triangular_residual = _matrix_l1_norm(upper)
    triangular_allowed = _TRIANGULAR_RTOL_FACTOR * max(n, 1) * eps * scale
    if torch.any(triangular_residual > triangular_allowed).item():
        worst = (triangular_residual / scale).amax().item()
        return (
            False,
            f"output is not lower triangular enough: relative_residual={worst:.3g}",
        )

    diagonal = torch.diagonal(output, dim1=-2, dim2=-1)
    if torch.any(diagonal <= 0).item():
        return False, "output diagonal must be strictly positive"

    # Disable TF32 so the reconstruction gate measures FP32 factorization
    # accuracy rather than tensor-core matmul approximation error.
    old_tf32 = torch.backends.cuda.matmul.allow_tf32 if data.is_cuda else False
    try:
        if data.is_cuda:
            torch.backends.cuda.matmul.allow_tf32 = False
        reconstruction = output @ output.transpose(-1, -2)
    finally:
        if data.is_cuda:
            torch.backends.cuda.matmul.allow_tf32 = old_tf32

    residual = _matrix_l1_norm(reconstruction - data)
    allowed = _RECON_RTOL_FACTOR * max(n, 1) * eps * scale
    if torch.any(residual > allowed).item():
        worst = (residual / scale).amax().item()
        return False, f"L @ L.T does not reconstruct A: relative_residual={worst:.3g}"

    scaled = (residual / (eps * max(n, 1) * scale)).amax().item()
    return True, f"scaled_reconstruction_residual={scaled:.3g}; batch={batch}; n={n}"
#!/usr/bin/env bash
# QR v2 differential-correctness guard.
#
# WHAT IT CATCHES — a kernel whose output does not depend on the current input's
# bytes: one that computes the factorization once (or keys a cache on the call
# ordinal, or on the shape) and then replays that answer for every later call. An
# honest kernel passes this guard trivially; it only ever changes the verdict for
# such a "memorizer".
#
# WHY EVAL MISSES IT — on the large benchmark shapes eval's _benchmark_batch_count
# caps the generated inputs at count=1 (the 256 MiB BENCHMARK_INPUT_BYTES_TARGET;
# e.g. 640x512 and 60x1024 each exceed it in a single draw), so the timed loop
# reuses ONE input object across all repeats. recheck=True re-validates every
# timed iteration, but always against that single reused input — which the
# memorizer answers correctly. So it is scored as the fastest submission and is
# never contradicted locally.
#
# HOW — re-runs the benchmark specs but feeds --seq (default 8) DISTINCT inputs
# per shape (fresh seeds base+1009*(index+1), plus a case rotation) and checks
# each output against its own input. A replayed/stale answer produces a blown-up
# QR residual on every input after the first -> FLAGGED.
#
# DOES NOT add or change shapes: (batch, n, cond) are copied verbatim from each
# benchmark spec — only the seed changes, and the case rotates where a `case`
# field already exists. It does not use the test specs at all.
#
# BOUNDARY — it cannot catch a cache keyed on the actual input content: 8 distinct
# inputs are 8 cache misses -> 8 correct recomputes -> CLEAN, yet that cache still
# beats eval for the same count=1 reason. This guard narrows that hole; it does
# not seal it.
#
# ENABLED: this guard runs on every validate (harness/validate.sh globs and runs
# guards/*.sh after the test shapes pass). It is an anti-reward-hack check, not a
# correctness gate, and it spends real GPU time on the large shapes — that cost is
# accepted as the price of catching memorizer/cache hacks the test shapes miss.
set -uo pipefail

REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../../.." && pwd)"
source "$REPO_DIR/harness/env.sh" "$@"

SPECS="$("$PYTHON" "$REPO_DIR/bin/gen_specs.py" "$PROBLEM_DIR/task.yml" --emit benchmarks)"
SPECFILE="$(mktemp)"; trap 'rm -f "$SPECFILE"' EXIT
printf '%s' "$SPECS" > "$SPECFILE"

cd "$PROBLEM_DIR" || exit 1
"$PYTHON" - "$SPECFILE" ${DIFF_GUARD_ARGS:-} <<'PY'
