                print(f"      call {call}: case={case} seed={seed} {message}")
            flagged.append(spec)
        else:
            print(f"  [{label:52}] ok")

    if flagged:
        print(f"\ndifferential correctness guard: FLAGGED {len(flagged)} shape(s)")
        return 2
    print("\ndifferential correctness guard: CLEAN")
    return 0


